export const MONUMENTS = JSON.parse("[{\"id\":\"n4846085726\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. Ю. Витте\",\"x\":-1743.1,\"z\":-2773.4,\"subject\":\"Q155329\",\"inscription\":\"Здесь с 1899 по 1915 год жил выдающийся государственный деятель России Сергей Юльевич Витте\"},{\"id\":\"w1147295661\",\"kind\":\"artwork\",\"sub\":\"painting\",\"x\":-1795.4,\"z\":-2812.5},{\"id\":\"w1147295662\",\"kind\":\"artwork\",\"sub\":\"painting\",\"x\":-1804.2,\"z\":-2808.6},{\"id\":\"n8930900534\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. Д. Кизиму\",\"x\":-3642.6,\"z\":-2797.3,\"subject\":\"Q360060\",\"inscription\":\"Дважды Герой Советского Союза летчик-космонавт генерал-полковник Кизим Леонид Денисович. Профессор, кандидат военных наук, талантливый педагог, организатор. Возглавлял академию с 1993 по 2001 год\"},{\"id\":\"n8971721785\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3639.1,\"z\":-2794.5,\"inscription\":\"Памятник архитектуры XVIII века Здание построено в 1795-1803 г.г. Архитектор Ф.И. Демерцов Охраняется государством\"},{\"id\":\"n10737731572\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. И. Антонову\",\"x\":-3434.4,\"z\":-2797.4,\"subject\":\"Q312153\",\"inscription\":\"Антонов Алексей Иннокентьевич, генерал армии. Его имя было присвоено Ленинградскому высшему военно-топографическому командному училищу.\"},{\"id\":\"n10737731573\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. К. Котлинскому\",\"x\":-3433.1,\"z\":-2796.5,\"subject\":\"Q20755757\",\"inscription\":\"Котлинский Владимир Карпович, подпоручик. Выпускник военно-топографического училища 1914 года. Возглавил контратаку \\\"мертвецов\\\" 06.08.1915 г. Крепость Осовец.\"},{\"id\":\"n3189624700\",\"kind\":\"memorial\",\"sub\":\"sculpture\",\"name\":\"Гребцам Российского флота\",\"x\":-3437.4,\"z\":-2820.3},{\"id\":\"n8665233272\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. В. Канторовичу\",\"x\":-2959.6,\"z\":-2794,\"subject\":\"Q107441\",\"inscription\":\"В этом доме с 1923 по 1975 год жил профессор Ленинградского государственного университета академик, лауреат Нобелевской премии Леонид Витальевич Канторович\"},{\"id\":\"n10737731574\",\"kind\":\"memorial\",\"sub\":\"sculpture\",\"name\":\"Военным топографам посвящается\",\"x\":-3433.5,\"z\":-2800.4},{\"id\":\"n970872770\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2840.6,\"z\":-2816.5,\"inscription\":\"В этом здании в 1937–1942 годах размещалась 7я ленинградская специальная средняя артиллерийская школа. Выпускники школы проявляли мужество и стойкость в годы войны и внесли большой вклад в укрепление обороноспособности страны в послевоенный период\"},{\"id\":\"n970872841\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. П. Павлову\",\"x\":-2809.3,\"z\":-2767.2,\"subject\":\"Q42985\",\"inscription\":\"В этом доме с 1892 г. по 1918 г. жил великий русский учёный-физиолог академик Иван Петрович Павлов\"}]");
